package android.view;public class ViewGroup extends View {public static class LayoutParams {public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public static class MarginLayoutParams extends LayoutParams {public int leftMargin,topMargin,rightMargin,bottomMargin;private int start=Integer.MIN_VALUE,end=Integer.MIN_VALUE;public MarginLayoutParams(int w,int h){super(w,h);}public int getMarginStart(){return start==Integer.MIN_VALUE?leftMargin:start;}public int getMarginEnd(){return end==Integer.MIN_VALUE?rightMargin:end;}public void setMarginStart(int v){start=v;}public void setMarginEnd(int v){end=v;}}}
